-- Owner-authorised PWD one-on-one options, 30 October 2026. VUV prices are local overrides.
-- Curriculum follows BuildProfitAI, with explicit coding/WordPress and owner-set mentorship periods.
BEGIN;
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pwd_lms_courses WHERE slug='full-ai-business-program') AND EXISTS(
 SELECT 1 FROM pwd_lms_orders o JOIN pwd_lms_courses c ON c.id=o.course_id WHERE c.slug IN('how-to-start-a-profitable-business','one-on-one-mentorship')) THEN
 RAISE EXCEPTION 'Legacy enrolments appeared: preserve their offer before replacing the unbooked programmes'; END IF;
 IF EXISTS(SELECT 1 FROM pwd_lms_courses WHERE slug IN('how-to-start-a-profitable-business','one-on-one-mentorship') AND currency<>'VUV') THEN RAISE EXCEPTION 'Unexpected currency/project'; END IF;
END $$;
INSERT INTO pwd_lms_courses(slug,title,description,introduction,kind,amount,currency,published,enrollment_open,private_sessions,is_private,requires_approval)
VALUES ('how-to-start-a-profitable-business','Business Creation & Digital Foundations — One-on-One','18 private 90-minute lessons over 6 weeks, three times a week. Then 1 month of follow-up mentorship. Build your business, from idea to launch.','Welcome to Business Creation & Digital Foundations — One-on-One. Learn the practical business skills Steve teaches in the October cohort, with private guidance and more time to apply them to your own business. Work through the connected process: create your offer, master Digi Assist AI, build your website or store, attract customers and organise delivery. You also learn how to package these skills into a digital agency service. Bring your own idea or existing business. During class, build your offer, website or ecommerce store, marketing assets and customer enquiry or order process. Finish by demonstrating the complete customer journey and agreeing your next priorities for mentorship. VUV 150,000 is the one-time fee for 18 scheduled one-on-one lessons (27 teaching hours) over 6 weeks, followed by 1 month of mentorship. Meet Steve three times a week for 90-minute lessons, with practice between sessions. Afterwards, mentorship is project guidance, review and troubleshooting: meet about once a week or arrange help when needed during the included period. Meetings are arranged together. Your assigned session notes and private recordings are available in your own course space. Domains, hosting, advertising and external subscriptions are separate. No income or sales results are guaranteed.','live',150000,'VUV',true,true,true,false,false),
('one-on-one-mentorship','AI, Coding & Software Development — One-on-One','18 private 90-minute lessons over 6 weeks, three times a week. Then 3 months of follow-up mentorship. Build the tools your business needs.','Welcome to AI, Coding & Software Development — One-on-One. Learn the AI, coding and delivery skills Steve uses in his own work. Build one software project of your choice during class and connect AI agents to practical business workflows. The training combines building, testing and deployment with content, video, meetings, customer service and administration. Choose a software idea that matters to you: for example, a booking system, stock tracker, customer portal, business dashboard or AI assistant. Agree a practical scope with Steve, then build its main workflow, connect its data, test it and deploy a working version during the programme. Use the three months of mentorship afterwards to refine and extend it. VUV 250,000 is the one-time fee for 18 scheduled one-on-one lessons (27 teaching hours) over 6 weeks, followed by 3 months of mentorship. Meet Steve three times a week for 90-minute lessons, with practice between sessions. Afterwards, mentorship is project guidance, review and troubleshooting: meet about once a week or arrange help when needed during the included period. Meetings are arranged together. Your assigned session notes and private recordings are available in your own course space. Domains, hosting, advertising and external subscriptions are separate. Includes three free months of Digi Assist AI Pro; continued use after that requires a paid subscription. No income or sales results are guaranteed.','live',250000,'VUV',true,true,true,false,false),
('full-ai-business-program','Complete Business & AI Programme — Both Phases','36 private 90-minute lessons over 12 weeks, three times a week. Then 3 months of follow-up mentorship after both phases. Create your business. Then build with AI.','Welcome to Complete Business & AI Programme — Both Phases. Learn both sets of practical skills in sequence: create and market your business, then build your chosen software and AI agent workflows. The complete package includes both project journeys and three months of mentorship after both phases. Complete your business launch project in the first phase, then build one software project of your choice in the second. Connect marketing, customer workflows and AI agents around your goals, with three months of follow-up mentorship after both phases. VUV 350,000 is the one-time fee for 36 scheduled one-on-one lessons (54 teaching hours) over 12 weeks, followed by 3 months of mentorship after both phases. Meet Steve three times a week for 90-minute lessons, with practice between sessions. Afterwards, mentorship is project guidance, review and troubleshooting: meet about once a week or arrange help when needed during the included period. Meetings are arranged together. Your assigned session notes and private recordings are available in your own course space. Domains, hosting, advertising and external subscriptions are separate. Includes three free months of Digi Assist AI Pro; continued use after that requires a paid subscription. No income or sales results are guaranteed.','live',350000,'VUV',true,true,true,false,false)
ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,introduction=excluded.introduction,kind=excluded.kind,amount=excluded.amount,currency=excluded.currency,published=true,enrollment_open=true,private_sessions=true,is_private=false,requires_approval=false;
CREATE OR REPLACE FUNCTION public.pwd_lms_mentorship_journey() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
DECLARE course_slug text; plan jsonb;
BEGIN
 SELECT slug INTO course_slug FROM pwd_lms_courses WHERE id=NEW.course_id AND private_sessions;
 IF course_slug IS NULL THEN RETURN NEW; END IF;
 plan := $plans${"how-to-start-a-profitable-business":[{"title":"Business idea, customers and business model","body":"Choose a customer problem, test demand and define your offer, costs, revenue and pricing."},{"title":"Business setup, branding and agency foundations","body":"Check your name and domain, plan registration and banking, develop your brand and choose the services your digital agency could offer."},{"title":"Mastering Digi Assist AI","body":"Practise prompts and the connected website, chatbot, booking, catalogue and business-document workspaces. Build a repeatable way to use AI in your daily work."},{"title":"Domains, hosting and professional email","body":"Choose and connect a domain, hosting and business email, keeping ownership and recovery details under your control."},{"title":"Build your business website with AI","body":"Use Digi Assist AI to build clear website pages, useful copy, mobile layouts and a working enquiry route. Review quality and basic search visibility."},{"title":"Build an ecommerce website","body":"Create a small store with products, descriptions and images. Plan payment options, order confirmation, delivery and returns; test the customer journey."},{"title":"Google Business Profile, SEO and analytics","body":"Check listing eligibility and ownership, prepare accurate business details and verification steps, and use website SEO and analytics to plan improvements."},{"title":"Facebook Page, Instagram and content planning","body":"Set up a useful business Page, present your offer and plan content for Facebook and Instagram with a clear customer action."},{"title":"Facebook and Instagram advertising","body":"Choose an ad objective, audience, budget, creative and destination. Prepare and review a campaign for your own permitted business offer."},{"title":"Affiliate niches, programmes and disclosures","body":"Choose relevant affiliate programmes and products, understand commission terms and prepare helpful recommendations with clear disclosures."},{"title":"Affiliate content, links and conversion tracking","body":"Create reviews and comparisons, set up tracked links and review clicks, referrals and conversions. Separate pending, approved and paid income."},{"title":"Digital marketing, email and customer conversations","body":"Combine useful content, email follow-up and analytics. Practise sales conversations and plan a campaign you can measure and improve."},{"title":"AI images and promotional video production","body":"Create a branded content brief, script, visual assets and an AI promotional video. Review facts and permissions before publication."},{"title":"Business chatbots, bookings and service packages","body":"Build a chatbot from approved business facts, connect enquiries and booking requests, and prepare service packages with a clear handover to you."},{"title":"CRM, quotations, invoices and receipts","body":"Organise leads and customer records, prepare quotes and invoices, record payments and plan follow-up using the demonstrated Digi Assist tools."},{"title":"Google Ads, retargeting and campaign refinement","body":"Understand search intent and keywords, plan a budget and retargeting, and improve your ad message, landing page and measurement."},{"title":"Set up and deliver your digital agency services","body":"Package website, ecommerce, marketing and AI services; price your work, prepare a proposal, onboard a client and plan delivery, handover and support."},{"title":"Business launch, demonstration and review","body":"Show your offer, website or store, marketing and customer workflow. Review results, improve weak points and agree your first month of mentorship priorities."}],"one-on-one-mentorship":[{"title":"AI fundamentals and practical prompting","body":"Use AI for research, reasoning, content and business tasks. Build reusable prompts and review output against your goals."},{"title":"Choose and scope your software project","body":"Choose one software idea, define users, screens and the main workflow, and agree what you will build during class."},{"title":"Design AI agents and automation workflows","body":"Map the work you want to delegate. Define agent instructions, connected tools, permissions and review steps; scope an automation audit."},{"title":"Customer-service agents, chatbots and bookings","body":"Build a useful assistant for enquiries and bookings, ground it in business facts and test handover and follow-up."},{"title":"CRM, marketing and administrative agents","body":"Connect leads, email, documents and follow-up. Build focused workflows for quotations, invoices or other repeated administrative tasks."},{"title":"AI video, content and meeting assistants","body":"Connect tools for research, scripts, video production and meeting preparation. Practise supported scheduling, notes, summaries, action lists and follow-up drafts."},{"title":"AI-assisted WordPress planning","body":"Plan a WordPress website, pages, plugins and a clear customer journey for your own business or a client."},{"title":"Build and improve WordPress with AI","body":"Use AI for content, layouts and useful integrations such as forms, bookings or ecommerce; review quality and troubleshoot errors."},{"title":"AI-assisted coding foundations","body":"Read, adapt and debug code with AI. Understand project files, versions, errors and how to review the changes you accept."},{"title":"No-code and AI application builders","body":"Start your chosen software project using appropriate app-building tools. Build its screens and first working user journey."},{"title":"Databases, user accounts and APIs","body":"Connect your project data, accounts and external services, using suitable permissions and access controls."},{"title":"Build your chosen software project","body":"Implement the main workflow of your own app or business programme, then connect the integrations or AI agent that support it."},{"title":"Testing, debugging and project quality","body":"Test your main user journey, data access and common failures. Fix problems and review security and reliability basics."},{"title":"Deploy your software and connected workflows","body":"Publish a working version, connect the services it needs and plan hosting, maintenance and support."},{"title":"Pricing, licensing and AI service delivery","body":"Package and price your software, automation audits and support. Prepare a clear scope, client handover and service plan."},{"title":"Design AI training for businesses and institutions","body":"Create a practical curriculum around real tasks for a business, government or community audience."},{"title":"Workshop facilitation and training proposals","body":"Practise demonstrations, exercises and facilitation; write a clear institutional training proposal."},{"title":"Software, AI agent and mini-training showcase","body":"Demonstrate your chosen software and connected AI workflow, deliver a short training and plan improvements for the mentorship period."}],"full-ai-business-program":[{"title":"Business idea, customers and business model","body":"Choose a customer problem, test demand and define your offer, costs, revenue and pricing."},{"title":"Business setup, branding and agency foundations","body":"Check your name and domain, plan registration and banking, develop your brand and choose the services your digital agency could offer."},{"title":"Mastering Digi Assist AI","body":"Practise prompts and the connected website, chatbot, booking, catalogue and business-document workspaces. Build a repeatable way to use AI in your daily work."},{"title":"Domains, hosting and professional email","body":"Choose and connect a domain, hosting and business email, keeping ownership and recovery details under your control."},{"title":"Build your business website with AI","body":"Use Digi Assist AI to build clear website pages, useful copy, mobile layouts and a working enquiry route. Review quality and basic search visibility."},{"title":"Build an ecommerce website","body":"Create a small store with products, descriptions and images. Plan payment options, order confirmation, delivery and returns; test the customer journey."},{"title":"Google Business Profile, SEO and analytics","body":"Check listing eligibility and ownership, prepare accurate business details and verification steps, and use website SEO and analytics to plan improvements."},{"title":"Facebook Page, Instagram and content planning","body":"Set up a useful business Page, present your offer and plan content for Facebook and Instagram with a clear customer action."},{"title":"Facebook and Instagram advertising","body":"Choose an ad objective, audience, budget, creative and destination. Prepare and review a campaign for your own permitted business offer."},{"title":"Affiliate niches, programmes and disclosures","body":"Choose relevant affiliate programmes and products, understand commission terms and prepare helpful recommendations with clear disclosures."},{"title":"Affiliate content, links and conversion tracking","body":"Create reviews and comparisons, set up tracked links and review clicks, referrals and conversions. Separate pending, approved and paid income."},{"title":"Digital marketing, email and customer conversations","body":"Combine useful content, email follow-up and analytics. Practise sales conversations and plan a campaign you can measure and improve."},{"title":"AI images and promotional video production","body":"Create a branded content brief, script, visual assets and an AI promotional video. Review facts and permissions before publication."},{"title":"Business chatbots, bookings and service packages","body":"Build a chatbot from approved business facts, connect enquiries and booking requests, and prepare service packages with a clear handover to you."},{"title":"CRM, quotations, invoices and receipts","body":"Organise leads and customer records, prepare quotes and invoices, record payments and plan follow-up using the demonstrated Digi Assist tools."},{"title":"Google Ads, retargeting and campaign refinement","body":"Understand search intent and keywords, plan a budget and retargeting, and improve your ad message, landing page and measurement."},{"title":"Set up and deliver your digital agency services","body":"Package website, ecommerce, marketing and AI services; price your work, prepare a proposal, onboard a client and plan delivery, handover and support."},{"title":"Business launch, demonstration and review","body":"Show your offer, website or store, marketing and customer workflow. Review results, improve weak points and agree your first month of mentorship priorities."},{"title":"AI fundamentals and practical prompting","body":"Use AI for research, reasoning, content and business tasks. Build reusable prompts and review output against your goals."},{"title":"Choose and scope your software project","body":"Choose one software idea, define users, screens and the main workflow, and agree what you will build during class."},{"title":"Design AI agents and automation workflows","body":"Map the work you want to delegate. Define agent instructions, connected tools, permissions and review steps; scope an automation audit."},{"title":"Customer-service agents, chatbots and bookings","body":"Build a useful assistant for enquiries and bookings, ground it in business facts and test handover and follow-up."},{"title":"CRM, marketing and administrative agents","body":"Connect leads, email, documents and follow-up. Build focused workflows for quotations, invoices or other repeated administrative tasks."},{"title":"AI video, content and meeting assistants","body":"Connect tools for research, scripts, video production and meeting preparation. Practise supported scheduling, notes, summaries, action lists and follow-up drafts."},{"title":"AI-assisted WordPress planning","body":"Plan a WordPress website, pages, plugins and a clear customer journey for your own business or a client."},{"title":"Build and improve WordPress with AI","body":"Use AI for content, layouts and useful integrations such as forms, bookings or ecommerce; review quality and troubleshoot errors."},{"title":"AI-assisted coding foundations","body":"Read, adapt and debug code with AI. Understand project files, versions, errors and how to review the changes you accept."},{"title":"No-code and AI application builders","body":"Start your chosen software project using appropriate app-building tools. Build its screens and first working user journey."},{"title":"Databases, user accounts and APIs","body":"Connect your project data, accounts and external services, using suitable permissions and access controls."},{"title":"Build your chosen software project","body":"Implement the main workflow of your own app or business programme, then connect the integrations or AI agent that support it."},{"title":"Testing, debugging and project quality","body":"Test your main user journey, data access and common failures. Fix problems and review security and reliability basics."},{"title":"Deploy your software and connected workflows","body":"Publish a working version, connect the services it needs and plan hosting, maintenance and support."},{"title":"Pricing, licensing and AI service delivery","body":"Package and price your software, automation audits and support. Prepare a clear scope, client handover and service plan."},{"title":"Design AI training for businesses and institutions","body":"Create a practical curriculum around real tasks for a business, government or community audience."},{"title":"Workshop facilitation and training proposals","body":"Practise demonstrations, exercises and facilitation; write a clear institutional training proposal."},{"title":"Software, AI agent and mini-training showcase","body":"Demonstrate your chosen software and connected AI workflow, deliver a short training and plan improvements for the mentorship period."}]}$plans$::jsonb -> course_slug;
 IF plan IS NOT NULL THEN
 INSERT INTO pwd_lms_lessons(course_id,order_id,title,position,content,section_title,published,recordings_published)
 SELECT NEW.course_id,NEW.id,lpad(n::text,2,'0')||' · '||(s->>'title'),n::int,
 (s->>'body')||E'\n\nScheduled private lesson: 90 minutes. Arrange the appointment with Steve. Notes and recordings are published to your own enrolment. Follow-up mentorship is a separate support stage after the scheduled training.',
 'Week '||(((n-1)/3)::int+1)::text,true,false
 FROM jsonb_array_elements(plan) WITH ORDINALITY AS v(s,n);
 ELSE
 INSERT INTO pwd_lms_lessons(course_id,order_id,title,position,content)
 SELECT NEW.course_id,NEW.id,title,position,'Your mentor will arrange your sessions and publish notes and recordings here.' FROM(VALUES(1,'Month 1 · Business foundations & AI'),(2,'Month 2 · Websites, WordPress & ecommerce'),(3,'Month 3 · AI coding, software & launch')) AS r(position,title);
 END IF;
 RETURN NEW;
END $$;
COMMIT;
